Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.
#[local] Ltac lia ::= L5FastLia.plia.

Import PMES.

Section NewLine2Pos16.
Context {SCFG_P : ScfgP}.
Variable L : asan_layout.
Variable ar : asan_run.
Variable C : asan_statics_cells.
Variable HI : asan_iface.
Hypothesis HIok : PmHeapIfaceA.asan_iface_ok L ar C SCFG HI.
Hypothesis LAY : L5A.as0_layout L C.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps (hl_segs L) (@mkst fx R (Z_to_bv 64 pc) M (seg_rom (hl_segs L))) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom (hl_segs L))) -> PMSA.fp_ok fx -> PMSA.fp_ok fx'.
Variable CL : Z.
Abbreviation IC := PMLA.C_xboth.
Abbreviation EC := PMESA.EC_xboth.
Abbreviation RSEGS := (hl_segs L).
Hypothesis APPEND_OK : PMESA.str_append_x_specA L ar HI IC CL ENLA.PC_APPEND.          (* [comment removed for export] *)
Hypothesis PUSHB_OK : PMESA.str_push_back_x_specA L ar HI CL ENLA.PC_PUSHB.            (* [comment removed for export] *)

Definition hid (P : Prop) : Prop := P.

Theorem new_line2_pos16_ok : forall (LBo : list (Z * Z)) (FF LK : list fframe) (cr : credit) (A : list (Z * Z)) (sp r V S2 kx bx d : Z) (rep : PML.srep),
  1 <= d -> sp mod 32 = 16 ->
  PMSA.cps_asan L ar HI 770716 r sp PMESA.NEWLINE_SCRA (LBo ++ PML.srep_blocks rep) FF LK cr A PMESA.NEWLINE_DA
    (fun R M => PMSA.a0 R V /\ PMESA.nl_reads L M V S2 d /\ PMSA.stksh ar M sp PMESA.NEWLINE_SCRA /\ PMESA.sink_atA L M S2 rep /\ PMLA.img_ro IC M /\ PMESA.screditA L CL cr rep kx bx /\
                len (PML.srep_chars rep) + (1 + 4 * d) <= CL /\ PMESA.objs_encA M FF V S2)
    (fun R M R' M' LB' cr' LBk W => exists (rep' : PML.srep),
